def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(r for r, row in enumerate(grid) if all(v == 5 for v in row))
    colors = {v for row in grid for v in row if v not in (0, 5)}
    counts = {}
    for color in colors:
        above = sum(v == color for row in grid[:sep] for v in row)
        below = sum(v == color for row in grid[sep + 1:] for v in row)
        counts[color] = (abs(above - below), above + below)
    color = max(colors, key=lambda c: counts[c])
    return [[color, color], [color, color]]
